import java.util.Scanner;

public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    String S = sc.next();
    char firstChar = S.charAt(0);
    int sLength = S.length();

    for (int i = 1; i < sLength; i++) {
        char ch = S.charAt(i);
        if (ch != firstChar) {
            System.out.println(i + 1);
            return;
        }
    }
}
